$\begin{align}
&\phantom{=}f'(x)
\\\\
&=\dfrac{d}{dx}\left(\dfrac1xe^x\right)
\\\\
&=\dfrac{d}{dx}\left(\dfrac1x\right)e^x+\dfrac1x\dfrac{d}{dx}(e^x)&&\gray{\text{The product rule}}
\\\\
&=\dfrac{d}{dx}\left(x^{-1}\right)e^x+\dfrac1x\dfrac{d}{dx}(e^x)&&\gray{\text{Write }\dfrac1x \text{as a power}}
\\\\
&=-1x^{-2}\cdot e^x+\dfrac1x\cdot e^x&&\gray{\text{Differentiate }x^{-1}\text{ and }e^x}
\\\\
&=-\dfrac{1}{x^{2}}\cdot e^x+\dfrac1x\cdot e^x&&\gray{\text{Rewrite with positive exponents}}
\\\\
&=e^x\left(\dfrac1x-\dfrac{1}{x^2}\right)&&\gray{\text{Simplify}}
\end{align}$
